--
-- Table structure for table `registration_vehicles`
--

DROP TABLE IF EXISTS `registration_vehicles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `registration_vehicles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `driver_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver_id_card` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `driver_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vehicle_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hawb_number` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `pcs` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_priority` tinyint(1) NOT NULL DEFAULT '0',
  `sort` int DEFAULT NULL,
  `id_registration_directly` bigint unsigned DEFAULT NULL,
  `expected_in_at` datetime NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `status` enum('none','sent','approve','reject','entering','exited') COLLATE utf8mb4_unicode_ci DEFAULT 'none',
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `fee_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `registration_vehicles_approved_by_foreign` (`approved_by`),
  KEY `registration_vehicles_id_registration_directly_foreign` (`id_registration_directly`),
  KEY `registration_vehicles_fee_id_foreign` (`fee_id`),
  CONSTRAINT `registration_vehicles_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `registration_vehicles_fee_id_foreign` FOREIGN KEY (`fee_id`) REFERENCES `fees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `registration_vehicles_id_registration_directly_foreign` FOREIGN KEY (`id_registration_directly`) REFERENCES `register_directlies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5050 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
